from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[2];H=R/'research/round121';rd=lambda p:json.loads(Path(p).read_text());dump=lambda p,x:Path(p).write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
def main():
 assert rd(H/'SCALAR_AUDIT.json')['n']==384;agg=rd(H/'scores_attempt001/AGGREGATE_ROWS.json');angles=rd(H/'ANGLE_ROWS_PRIVATE.json');physical=rd(H/'PHYSICAL_ROWS_PRIVATE.json');conc=rd(H/'CONCENTRATION.json');q=rd(H/'QUALIFICATION.json');summ=[]
 for src in ['all_three_equal','waymo','drone','quad']:
  aa=angles if src=='all_three_equal' else [r for r in angles if r['source']==src];phys=physical if src=='all_three_equal' else [r for r in physical if r['source']==src]
  for kind in ['P','RGB','D','wrong_P','wrong_RGB','wrong_D','random','oracle1','oracle10']:
   v=[x[kind] for x in aa if kind in x and x[kind] is not None];pp=[x for x in phys if x['arm']==kind];summ.append({'source':src,'arm':kind,'gradient_cosine_n':len(v),'gradient_cosine_mean':float(np.mean(v)) if v else None,'gradient_cosine_median':float(np.median(v)) if v else None,'positive_gradient_cosines':sum(x>0 for x in v),'task_surrogate_improved':sum(r['oracle_loss_delta']< -1e-12 for r in pp),'task_surrogate_worsened':sum(r['oracle_loss_delta']>1e-12 for r in pp),'n':len(pp)})
 dump(H/'SIGNAL_SUMMARY.json',summ)
 def m(arm):return next(x['mIoU_percent'] for x in agg if x['frame_group']=='all' and x['source']=='all_three_equal' and x['arm']==arm)
 dec={'scope':'SOURCE_ONLY_CONTROLLED_DIAGNOSIS_NOT_UNLABELED_TTA','source_labels_used':True,'target_data_read':False,'new_source_training':False,'deployed_source_weights_changed':False,'GN224_oracle1_gain_pp':m('oracle1')-m('context_zero'),'GN224_oracle10_gain_pp':m('oracle10')-m('context_zero'),'qualified_aux_signal':q['picked_on_predeclared_source_group0'] if q['qualified'] else None,'qualification_pass':q['qualified'],'automatic_target_deployment':False,'TTA_adopted':False,'FINAL_access':False};dump(H/'DECISION.json',dec)
 lines=['# R121 — 源域受控GN224能力与信号诊断','','本轮只做源域受控诊断。三个epoch100源模型及现有R91双向模块不重新训练；每个输入上暂时修改224个RGB GroupNorm仿射参数，测试后恢复。源域GT仅用于oracle能力对照与事后评分，oracle状态不部署、不称为TTA。没有目标域推理或评分、外部专家、新框或FINAL访问。','','## 竞争解释与范围','','R120的真实GN写回和实时语义路径都已核实，但深度更新没有超过同信息冻结/错配/随机对照。缺少的区分是：在同一接口、同一单步范数下，grounding监督能否产生有益选框变化？若能而物理监督不能，主要是信号方向；若GT同预算也几乎无效，则不能只归因于监督不够准。','','这不重复R77：R77测试102498个Adapter/交互参数和另一软IoU监督；这里仅RGB GN224，原生点—文字基础h/U硬固定，只让sourceA的RGB late与实际竞争残差r改变。它也是当前A源域能力代理，不能推出跨域融合F的TTA必然有效。','','## 数据与固定条件','','三个source各128条已暴露的source VAL，Waymo82、Drone2、Quad3个场景。它们曾用于既有模块选择，不是独立确认集。沿用现成prefix/标定后RGB数组/路由/已封存IoU；未打开原媒体或标注重新计算框。原始A256框、query身份、六层decoder位置、完整文字全部固定。没有源域B/C观测缓存，因此本轮不制造源域三采样或R59对照；目标域R59及ABC强基线的既有结果保留在R120等完整记录，不在不同数据上假比较。','','一个固定全局source-frame哈希将样本分成group0/group1，同帧同组。各来源的group计数在PREFLIGHT.json。选择规则在模型结果前锁定：只用group0选P/RGB/D中总体最好的一项；group1必须超过自身零步、对应错配、等范数随机。此规则只用于源域诊断资格，不把已经曝光的source VAL包装成新测试，也不会自动部署。','','## 干预','','P为既有点特征恢复，RGB为互补遮挡图像恢复，D为图像单支测量稀疏深度恢复。每项原始梯度独立计算，统一归一到source GN范数1%；76001/2遮挡及query锚点保护不变。P/RGB沿用原错配点—像素关系；D将有效深度格目标循环错配。随机GN同修改范数。没有混合损失权重或步长扫描。','','oracle1使用真实最佳IoU候选集合的概率质量负对数，1e-8并列范围；全零oracle输入不构造任意正标签，仍留在总分分母。oracle10为预设10次同半径GT方向尝试、9档固定Armijo回溯，累计范数上界10倍。后者只测受控容量，不是无标签验收算法。降低该代理损失也必须与实际IoU分开。','','## 实现核验与失败记录','','预检384条的框—seed支持、query锚点、缓存标签和形状通过。6条真实工程样本逐臂检查GN更新后native h/U仍逐值一致、作用域仅6张量224参数、逐例恢复。首次工程断言错误地比较原始每query token概率sigmoid(logodds)与跨query softmax(logodds)；实际隐藏态、文字及匹配头完全一致。修正的只是验证口径，失败代码、日志和前后lock全部保留，见ASSERTION_AMENDMENT.json。正式预测规则未因任务成绩修改。','','## 全384源域任务结果','','单位为百分数。all_three_equal逐source等权；由于每源128条，它与384条总体均值相同。group内仍按source等权，避免组大小不同改变来源比例。','','| source | 方法 | n | mIoU% | Acc25% | Acc50% |','|---|---|---:|---:|---:|---:|']
 for x in agg:
  if x['frame_group']=='all':lines.append(f"| {x['source']} | {x['arm']} | {x['n']} | {x['mIoU_percent']:.6f} | {x['Acc25_percent']:.6f} | {x['Acc50_percent']:.6f} |")
 lines+=['','## 源域资格与决定','','```json',json.dumps(q,indent=2),json.dumps(dec,indent=2),'```','','若未通过，不把P/RGB/D依次搬到目标域继续试，也不增加GN幅度来找正数。即使通过，也需另行锁定一个有依据的目标验证；若选中D，R120已有相同信号的目标负结果，不重新运行。没有GT筛选部署伪标签、逐平台拼方法或删除负例。','','## 方向与任务变化','','```json',json.dumps(summ,indent=2),'```','','梯度角度只是局部代理：正向角度或恢复损失下降不能代替Top1/IoU改善。oracle1与oracle10也不同预算，不能把后者当同成本获胜方法。','','## 全部正负贡献与案例边界','','```json',json.dumps(conc,indent=2),'```','','所有IoU改善、恶化、零变化及匿名场景结果公开。good/failure按数值变化定义，未看私有图像的实例身份记为UNKNOWN；换query不自动等于换物体。最大单例贡献按完整384分母报告，不据此挑选适应输入。Drone仅2个、Quad仅3个源场景，不能用逐描述误差条冒充跨场景总体保证。','','## 审计与部署边界','','```json',json.dumps(rd(H/'NATIVE_AUDIT.json'),indent=2),json.dumps(rd(H/'SCALAR_AUDIT.json'),indent=2),'```','','独立CPU重算末端匹配/竞争接口、实际GN状态范数、三种物理组件与六种正确/错配梯度；另程序逐值读取封存候选IoU、核对总体与成对变化。所有执行经hard09:00资源guard。逐例seconds覆盖全部实验臂的缓存后缀与诊断计算，不是单方法端到端延迟。source epoch100及已有双向模块文件SHA保持，oracle临时状态只在私有证据中，公开包排除原始媒体、文字、坐标、ID、特征、梯度和权重。','','本轮的价值是对当前接口/预算与辅助方向作受控区分，不是得到新的TTA正结果。没有把source GT拟合能力或无标签辅助下降冒充跨域增益。'];(H/'REPORT.md').write_text('\n'.join(lines)+'\n');print(dec,flush=True)
if __name__=='__main__':main()
